import { component, verifySignature } from "http-message-sig";
import { describe, expect, it } from "vitest";
import { u8ToB64 } from "../src/base64";
import { verifierFromJWK } from "../src/crypto";
import vectors from "./test_data/web_bot_auth_directory_response_v1.json";

describe.each(vectors)("directory response vector: $name", (vector) => {
  it("has a valid content digest and core signature", async () => {
    const digest = await crypto.subtle.digest(
      "SHA-256",
      new TextEncoder().encode(vector.response.body)
    );
    expect(vector.response.headers["content-digest"]).toBe(
      `sha-256=:${u8ToB64(new Uint8Array(digest))}:`
    );

    const request = {
      kind: "request",
      method: vector.request.method,
      targetUri: vector.request.target_url,
      fields: Object.entries(vector.request.headers).map(([name, value]) => ({
        name,
        value,
      })),
    } satisfies import("http-message-sig").RequestDescriptor;
    const response = {
      kind: "response",
      status: vector.response.status,
      fields: Object.entries(vector.response.headers).map(([name, value]) => ({
        name,
        value,
      })),
      request,
    } satisfies import("http-message-sig").ResponseDescriptor;
    const verifier = await verifierFromJWK(vector.public_key);
    await expect(
      verifySignature(response, {
        label: "binding0",
        policy: {
          algorithms: ["ed25519"],
          requiredComponents: [
            component("@authority", { req: true }),
            "content-digest",
          ],
          requiredParameters: ["created", "expires", "keyid", "alg", "tag"],
          now: 1_735_689_600,
        },
        resolveVerifier: () => verifier,
      })
    ).resolves.toMatchObject({ verifier, label: "binding0" });
  });
});

/// This script generates test vectors for https://datatracker.ietf.org/doc/draft-meunier-webbotauth-httpsig-directory/
/// and https://datatracker.ietf.org/doc/draft-meunier-webbotauth-registry/
/// The vectors are generated in JSON format
///
/// It takes one positional argument: [directory] which is where the vectors should be written in JSON

import type {
  RequestDescriptor,
  ResponseDescriptor,
  Signer,
} from "http-message-sig";

const { sign } = await import("../dist/index.mjs");

const { signerFromJWK } = await import("../dist/crypto.mjs");

const { component, createSignature } = await import("http-message-sig");

const crypto = await import("crypto");
const fs = await import("fs");
const path = await import("path");

const SIGNATURE_AGENT_HEADER = "https://signature-agent.test";
const ORIGIN_URL = "https://example.com/path/to/resource";

// Nonces are deterministic so vector updates are reproducible. The public seed
// is drand round 29865500 from:
// https://drand.cloudflare.com/52db9ba70e0cc0f6eaf7803dd07447a1f5477735fd3f661792ba94600c84e971/public/29865500
// Each nonce is base64(sha512(<round>:<randomness>:<jwk.kty>:<signature label>)).
const DRAND_ROUND = 29865500;
const DRAND_RANDOMNESS =
  "4901231f69a4e411e699f96485790415e83c56d1a8ef81acdf1bbdd75f6a2332";

function nonceFor(jwk: JsonWebKey, label: string): string {
  return crypto
    .createHash("sha512")
    .update(`${DRAND_ROUND}:${DRAND_RANDOMNESS}:${jwk.kty}:${label}`)
    .digest("base64");
}

interface TestVector {
  key: JsonWebKey;
  target_url: string;
  created_ms: number;
  expires_ms: number;
  nonce: string;
  label: string;
  signature: string;
  signature_input: string;
  signature_agent?: string;
  signature_agent_key?: string;
}

interface SignatureAgentVector {
  name: string;
  header: string;
  entries: {
    label: string;
    uri: string;
    type: "directory" | "jwks_uri" | "cimd";
  }[];
}

interface RegistryVector {
  name: string;
  registry_txt: string;
  signature_agent_cards: string[];
}

interface SignatureAgentCardVector {
  name: string;
  url: string;
  card: unknown;
  valid: boolean;
  error?: string;
}

interface DirectoryResponseVector {
  name: string;
  public_key: {
    kty: "OKP";
    crv: "Ed25519";
    kid: string;
    x: string;
    use: "sig";
  };
  request: {
    method: "GET";
    target_url: string;
    headers: Record<string, string>;
  };
  response: {
    status: 200;
    headers: Record<string, string>;
    body: string;
  };
  signature_base: string;
}

async function generateTestVectors(jwk: JsonWebKey): Promise<TestVector[]> {
  const now = new Date("2025-01-01T00:00:00Z");
  const created = now;
  // Use a far-future expiry so test vectors never expire during conformance testing.
  const expires = new Date(now.getTime() + 3_153_600_000_000);
  const signer = await signerFromJWK(jwk);

  const label = "sig1";
  const nonce = nonceFor(jwk, label);
  let request = new Request(ORIGIN_URL);
  const signedHeaders = await sign(request, {
    signer,
    created,
    expires,
    nonce,
    label,
  });

  const labelWithAgent = "sig2";
  const nonceWithAgent = nonceFor(jwk, labelWithAgent);
  const signatureAgentKey = "agent2";
  request = new Request(ORIGIN_URL, {
    headers: {
      "Signature-Agent": `${signatureAgentKey}="${SIGNATURE_AGENT_HEADER}"`,
    },
  });
  const signedHeadersWithAgent = await sign(request, {
    signer,
    created,
    expires,
    nonce: nonceWithAgent,
    label: labelWithAgent,
    signatureAgentKey,
  });

  return [
    {
      key: jwk,
      target_url: ORIGIN_URL,
      created_ms: created.getTime(),
      expires_ms: expires.getTime(),
      nonce,
      label,
      signature: signedHeaders.signature,
      signature_input: signedHeaders.signatureInput,
    },
    {
      key: jwk,
      target_url: ORIGIN_URL,
      created_ms: created.getTime(),
      expires_ms: expires.getTime(),
      nonce: nonceWithAgent,
      label: labelWithAgent,
      signature: signedHeadersWithAgent.signature,
      signature_input: signedHeadersWithAgent.signatureInput,
      signature_agent: request.headers.get("Signature-Agent") ?? undefined,
      signature_agent_key: signatureAgentKey,
    },
  ];
}

async function generateDirectoryResponseVector(
  jwk: JsonWebKey
): Promise<DirectoryResponseVector> {
  if (jwk.kty !== "OKP" || jwk.crv !== "Ed25519" || !jwk.x) {
    throw new Error("directory response vector requires an Ed25519 JWK");
  }

  const signer = await signerFromJWK(jwk);
  const publicKey: DirectoryResponseVector["public_key"] = {
    kty: "OKP",
    crv: "Ed25519",
    kid: signer.keyid,
    x: jwk.x,
    use: "sig",
  };
  const body = JSON.stringify({ keys: [publicKey] });
  const contentDigest = `sha-256=:${crypto.createHash("sha256").update(body).digest("base64")}:`;
  const request = {
    kind: "request",
    method: "GET",
    targetUri:
      "https://signature-agent.test/.well-known/http-message-signatures-directory",
    fields: [
      {
        name: "accept",
        value: "application/http-message-signatures-directory+json",
      },
    ],
  } satisfies RequestDescriptor;
  const response = {
    kind: "response",
    status: 200,
    fields: [
      {
        name: "content-type",
        value: "application/http-message-signatures-directory+json",
      },
      { name: "content-digest", value: contentDigest },
    ],
    request,
  } satisfies ResponseDescriptor;
  let signatureBase: string | undefined;
  const capturingSigner: Signer = {
    algorithm: signer.algorithm,
    async sign(data) {
      signatureBase = new TextDecoder().decode(data);
      return signer.sign(data);
    },
  };
  const signatureHeaders = await createSignature(response, {
    label: "binding0",
    signer: capturingSigner,
    components: [component("@authority", { req: true }), "content-digest"],
    parameters: {
      created: 1735689600,
      keyid: signer.keyid,
      alg: signer.algorithm,
      expires: 4889289600,
      tag: "http-message-signatures-directory",
    },
  });
  if (signatureBase === undefined) {
    throw new Error("directory response was not signed");
  }

  return {
    name: "ed25519",
    public_key: publicKey,
    request: {
      method: "GET",
      target_url: request.targetUri,
      headers: { accept: request.fields[0].value },
    },
    response: {
      status: 200,
      headers: {
        "content-type": response.fields[0].value,
        "content-digest": response.fields[1].value,
        Signature: signatureHeaders.signature,
        "Signature-Input": signatureHeaders.signatureInput,
      },
      body,
    },
    signature_base: signatureBase,
  };
}

